const out = $input.first().json.stdout || "";
const parts = out.split("===FILES===");
const secretsRaw = parts[0].replace("===SECRETS===", "").trim();
let secrets = {};
try { secrets = JSON.parse(secretsRaw); } catch (e) {}
const lines = (parts[1] || "").split("\n").map(s => s.trim()).filter(Boolean);
const chatMap = { "Юра": "599756870", "Катя": "599756870", "Коля": "599756870", "Вова": "599756870" };
const byManager = {};
for (const p of lines) {
  const m = p.match(/\/srv\/altek\/Сотрудники\/([^/]+)\//);
  const manager = m ? m[1] : "Неизвестно";
  const type = p.includes("/Заявка/") ? "заявка" : "тендер";
  const pp = p.split("/");
  const file = pp[pp.length - 1];
  const folder = pp[pp.length - 2];
  if (!byManager[manager]) byManager[manager] = [];
  byManager[manager].push("\u2022 " + type + ": " + folder + "/" + file);
}
const items = [];
for (const [manager, files] of Object.entries(byManager)) {
  items.push({ json: {
    manager: manager,
    chat_id: chatMap[manager] || "599756870",
    max_token: secrets.max_token || "",
    text: "Новые файлы в вашей папке (" + files.length + "):\n" + files.join("\n") + "\n\nАгент приступает к обработке."
  }});
}
return items;
